package com.ruoyi.generator.controller;

import java.util.List;
import java.util.Map;
import com.ruoyi.common.core.controller.BaseController;
import com.ruoyi.common.core.domain.AjaxResult;
import com.ruoyi.common.core.page.TableDataInfo;
import com.ruoyi.generator.domain.GenTable;
import com.ruoyi.generator.service.IGenTableService;
import jakarta.servlet.http.HttpServletResponse;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.security.access.prepost.PreAuthorize;
import org.springframework.web.bind.annotation.*;

@RestController
@RequestMapping("/tool/gen")
public class GenController extends BaseController {

    private final IGenTableService genTableService;

    public GenController(IGenTableService genTableService) {
        this.genTableService = genTableService;
    }

    @PreAuthorize("@ss.hasPermi('tool:gen:list')")
    @GetMapping("/list")
    public TableDataInfo genList(GenTable genTable) {
        startPage();
        List<GenTable> list = genTableService.selectGenTableList(genTable);
        return getDataTable(list);
    }

    /** 导入表结构：读 information_schema → 存 gen_table / gen_table_column */
    @PreAuthorize("@ss.hasPermi('tool:gen:import')")
    @PostMapping("/importTable")
    public AjaxResult importTableSave(String tables) {
        String[] tableNames = tables.split(",");
        List<GenTable> tableList = genTableService.selectDbTableListByNames(tableNames);
        genTableService.importGenTable(tableList);
        return success();
    }

    /** 生成代码：模板渲染后 zip 流下载 */
    @PreAuthorize("@ss.hasPermi('tool:gen:code')")
    @GetMapping("/batchGenCode")
    public void batchGenCode(HttpServletResponse response, String tables) {
        genTableService.generatorCode(tables.split(","), response);
    }
}

